records["Core/profile_data.lua"]={bytes=13895,hash=3810377379,oldBytes=13787,oldHash=2953815205,changes={{at=3696,current="-- The desired-stock feature is retired. An existing saved stockTargets map\n-- is inert data: copies, transfers and validation carry it unread as long as\n-- it is plain table data.\nlocal function validStockTargets(_,profile)\n",previous="-- Reject malformed optional stock before generic recursive profile copying.\nlocal function validStockTargets(addon,profile)\n"},{at=4018,current="    return plan==nil or type(plan)=='table' and getmetatable(plan)==nil\n",previous="    return plan==nil or addon.StockTargets.Validate(plan)==true\n"},{at=7302,current="            -- Retired desired-stock data: plain tables only, carried unread.\n",previous="            -- Closed optional schema was checked before copying the profile.\n"}}}
