records["Locales/enUS.lua"]={bytes=260936,hash=152095792,oldBytes=260311,oldHash=227334449,changes={{at=907,current="L['/rm perf engine [lean|standard] - Show or choose the rotation evaluation engine.'] = '/rm perf engine [lean||standard] - Show or choose the rotation evaluation engine.'\nL['Usage: /rm perf engine [lean|standard]'] = 'Usage: /rm perf engine [lean||standard]'\nL['Evaluation engine: %s'] = true\n",previous=""},{at=8356,current="",previous="L[\"Invalid stock targets in profile %s (%s); data preserved.\"] = true\nL[\"Invalid stock targets; data preserved.\"] = true\n"},{at=19739,current="L[\"Idle Re-check Interval (seconds)\"] = true\nL[\"Auto-Switch Re-check Interval (seconds)\"] = true\n",previous=""},{at=50299,current="L[\"Drag to resize the list. Double-click to reset.\"] = true\n",previous=""},{at=80445,current="L[\"Help.Announces.overview\"] = \"Announce selected spell casts or item uses independently of your active rotation, or invoke a configured Via Script/Macro entry directly. Select an entry in the sidebar, or use New to prepare one. The trigger applies to every ordered output card; each card has its own destination and conditions. These settings do not cast spells or use items. Cast-triggered announcements follow RM's combat-data policy and do not run on reference-only clients.\"\nL[\"Help.Announces.name\"] = \"An optional name identifies this announcement in the sidebar. Without one, the action name or Via Script/Macro identifier is used. Changing this display name does not change the watched action or callable identifier.\"\nL[\"Help.Announces.type\"] = \"Choose Spell, Pet Spell, Item or Via Script/Macro. Changing type clears the previous action and exact-rank choice. Via Script/Macro uses an Identifier instead of a cast event or stored action; switching back restores the event selector. Choosing the current type keeps its fields.\"\n",previous="L[\"Help.Announces.overview\"] = \"Announce selected spell casts or item uses independently of your active rotation, or invoke a configured Via Macro entry directly. Select an entry in the sidebar, or use New to prepare one. The trigger applies to every ordered output card; each card has its own destination and conditions. These settings do not cast spells or use items. Cast-triggered announcements follow RM's combat-data policy and do not run on reference-only clients.\"\nL[\"Help.Announces.name\"] = \"An optional name identifies this announcement in the sidebar. Without one, the action name or Via Macro identifier is used. Changing this display name does not change the watched action or callable identifier.\"\nL[\"Help.Announces.type\"] = \"Choose Spell, Pet Spell, Item or Via Macro. Changing type clears the previous action and exact-rank choice. Via Macro uses an Identifier instead of a cast event or stored action; switching back restores the event selector. Choosing the current type keeps its fields.\"\n"},{at=82757,current="L[\"Help.Announces.event\"] = \"For automatic action types, choose which observed cast event triggers this entry. A start, stop, interruption, failure or delay is different from a successful cast. Client support determines which events and observations are available. Via Script/Macro has no cast event.\"\n",previous="L[\"Help.Announces.event\"] = \"For automatic action types, choose which observed cast event triggers this entry. A start, stop, interruption, failure or delay is different from a successful cast. Client support determines which events and observations are available. Via Macro has no cast event.\"\n"},{at=83885,current="L[\"Help.Announces.announce\"] = \"Choose a chat destination, local output, a named Emote or Audible. Emote replaces Text with an emote selector and optional recipient. Audible replaces Text with Sound. Text is retained when switching modes. Say, Yell, Whisper and named joined channels are offered only for Via Script/Macro and remain subject to native restrictions.\"\n",previous="L[\"Help.Announces.announce\"] = \"Choose a chat destination, local output, a named Emote or Audible. Emote replaces Text with an emote selector and optional recipient. Audible replaces Text with Sound. Text is retained when switching modes. Say, Yell, Whisper and named joined channels are offered only for Via Macro and remain subject to native restrictions.\"\n"},{at=85207,current="",previous="L[\"Test /cheer\"] = true\nL[\"Emote report\"] = true\nL[\"Emote diagnostics\"] = true\nL[\"Help.Announces.diagnostics\"] = \"Test /cheer sends one targetless cheer when clicked and opens a copyable report. It does not apply pending settings or retry a spell announcement. Emote report opens the latest automatic-emote and click-test observations without sending anything. Call completion is not proof of visible output. Automatic Say and Yell are unavailable; saved entries retain their text and can be changed to another destination.\"\n"},{at=85584,current="L[\"Help.Announces.emote_target\"] = \"For cast entries, checked directs the emote to the recipient recorded for this exact cast, including click casting. It does not use your current target or a previous cast's recipient. For Via Script/Macro, checked uses the supplied macro unit. A missing recipient skips targeted output. Unchecked performs the emote without a target.\"\n",previous="L[\"Help.Announces.emote_target\"] = \"For cast entries, checked directs the emote to the recipient recorded for this exact cast, including click casting. It does not use your current target or a previous cast's recipient. For Via Macro, checked uses the supplied macro unit. A missing recipient skips targeted output. Unchecked performs the emote without a target.\"\n"},{at=86275,current="L[\"Help.Announces.substitutions\"] = \"For cast entries, {{spell}} is a spell link, {{item}} an item link and {{event}} the localized event name. {{target}} uses the recorded cast target, with the last recorded target for that spell as a fallback; it does not automatically use your selected target or your name. Unavailable cast substitutions can remain unchanged. Via Script/Macro instead uses its supplied target and spell, {{event}} becomes Via Script/Macro, and required missing inputs skip output; this API supplies no {{item}}.\"\n",previous="L[\"Help.Announces.substitutions\"] = \"For cast entries, {{spell}} is a spell link, {{item}} an item link and {{event}} the localized event name. {{target}} uses the recorded cast target, with the last recorded target for that spell as a fallback; it does not automatically use your selected target or your name. Unavailable cast substitutions can remain unchanged. Via Macro instead uses its supplied target and spell, {{event}} becomes Via Macro, and required missing inputs skip output; this API supplies no {{item}}.\"\n"},{at=87262,current="L[\"Help.Announces.save\"] = \"Edits stay in a draft until Apply. Complete the action or Via Script/Macro identifier and other required fields before saving. Discard abandons changes to saved announcements; Cancel closes a new creation draft. Leaving pending changes offers Apply, Discard or Cancel navigation.\"\nL[\"Help.Announces.collections\"] = \"Use the sidebar buttons to create, duplicate, transfer or compare announcements. Apply saves the imported draft; Compare does not merge entries. Via Script/Macro Duplicate assigns a distinct identifier and every copied output gets a fresh identity. Series exports use version 2; version 1 remains available for legacy single-output entries. Imports and Apply reject ambiguous identifiers. The red trash permanently deletes the selected saved entry after confirmation. Resolve pending edits first; deletion does not carry into the next selected draft.\"\n",previous="L[\"Help.Announces.save\"] = \"Edits stay in a draft until Apply. Complete the action or Via Macro identifier and other required fields before saving. Discard abandons changes to saved announcements; Cancel closes a new creation draft. Leaving pending changes offers Apply, Discard or Cancel navigation.\"\nL[\"Help.Announces.collections\"] = \"Use the sidebar buttons to create, duplicate, transfer or compare announcements. Apply saves the imported draft; Compare does not merge entries. Via Macro Duplicate assigns a distinct identifier and every copied output gets a fresh identity. Series exports use version 2; version 1 remains available for legacy single-output entries. Imports and Apply reject ambiguous identifiers. The red trash permanently deletes the selected saved entry after confirmation. Resolve pending edits first; deletion does not carry into the next selected draft.\"\n"},{at=124804,current="L[\"Help.General.idle_poll\"] = \"Out of combat with no target and no focus, Rotation Master skips a polling tick unless something it watches has changed: auras, cooldowns, health or power of you, your pet or party, movement, casting, equipment, bags, form, pets or group. It still re-checks at least this often, for time-based conditions (aura or cooldown remaining), distance, and custom code. In combat, with any target or focus, or while configuration is open, every polling tick is evaluated. Zero evaluates every polling tick.\"\nL[\"Help.General.autoswitch_poll\"] = \"With automatic switching, Rotation Master checks this often, in and out of combat, whether a different rotation's switch conditions now match, so conditions that change on their own (nearby enemy count, threat, movement, health) take effect. Target, focus and pet changes are checked straight away. Zero turns automatic switching off. Choosing a rotation manually still overrides automatic switching until you choose Auto again.\"\n",previous=""},{at=154719,current="",previous="L[\"Stock targets\"] = true\n"},{at=154720,current="",previous="L[\"Reset targets\"] = true\n"},{at=154721,current="",previous="L[\"Reset invalid stock targets? This cannot be undone.\"] = true\n"},{at=154722,current="",previous="L[\"Add stock target\"] = true\n"},{at=154723,current="",previous="L[\"No stock targets.\"] = true\n"},{at=154744,current="",previous="L[\"Complete the stock target settings before applying.\"] = true\n"},{at=154978,current="",previous="L[\"All saved minimums met.\"] = true\nL[\"No enabled saved targets.\"] = true\nL[\"%d saved targets below minimum.\"] = true\nL[\"%d below minimum; %d unknown.\"] = true\nL[\"Saved stock counts pending.\"] = true\nL[\"Apply or discard page changes to assess saved targets.\"] = true\nL[\"Saved stock readiness unavailable.\"] = true\n"},{at=154979,current="",previous="L[\"Stock counts pending.\"] = true\n"},{at=154980,current="",previous="L[\"Stock counts ready.\"] = true\n"},{at=154981,current="",previous="L[\"Stock counts unavailable.\"] = true\n"},{at=154982,current="",previous="L[\"Carried: %s\"] = true\n"},{at=154983,current="",previous="L[\"Shortage: %s\"] = true\n"},{at=154984,current="",previous="L[\"Copy shortage list\"] = true\n"},{at=154985,current="",previous="L[\"Apply or discard page changes and refresh stock counts before copying.\"] = true\n"},{at=154986,current="",previous="L[\"Stock shortage list\"] = true\n"},{at=162578,current="L[\"Stop CPU capture\"] = true\nL[\"Stop runtime capture\"] = true\nL[\"Stop cast capture\"] = true\nL[\"Help.General.cast_capture\"] = \"Record spell cast receipts for thirty seconds without changing settings or gameplay polling. While it runs this button reads Stop cast capture and ends the capture early, keeping what was recorded.\"\nL[\"Help.General.cast_report\"] = \"Open the copyable cast receipt report. It stays disabled until a cast capture has produced a report and while a capture is running.\"\n",previous=""},{at=184280,current="L[\"Help.Announces.conditions\"] = \"Optional conditions use the Announcement condition list and All, Any and Not groups. For spell, pet and item announcements, they run when the configured action and event match. For Via Script/Macro, they run when you invoke the saved identifier. Each output card checks its own conditions. Only a matching result allows that output; unavailable data skips that card while later cards remain independent. In Group can check the Spell recipient recorded for this cast, including click casting, without using your selected target. Choose Announcement target to check the spell recipient for automatic entries, or the supplied unit for Via Script/Macro; Whisper uses that same supplied unit. Automatic entries pass the recorded recipient name to native unit queries. A missing or unresolvable recipient skips its required condition; an unrelated selected target is never substituted. Missing or ambiguous required recipients do not match. Apply in the condition editor updates the announcement draft; Apply on Announces saves it. Cancel or Discard abandons draft changes.\"\n",previous="L[\"Help.Announces.conditions\"] = \"Optional conditions use the Announcement condition list and All, Any and Not groups. For spell, pet and item announcements, they run when the configured action and event match. For Via Macro, they run when you invoke the saved identifier. Each output card checks its own conditions. Only a matching result allows that output; unavailable data skips that card while later cards remain independent. In Group can check the Spell recipient recorded for this cast, including click casting, without using your selected target. Choose Announcement target to check the spell recipient for automatic entries, or the supplied unit for Via Macro; Whisper uses that same supplied unit. Automatic entries pass the recorded recipient name to native unit queries. A missing or unresolvable recipient skips its required condition; an unrelated selected target is never substituted. Missing or ambiguous required recipients do not match. Apply in the condition editor updates the announcement draft; Apply on Announces saves it. Cancel or Discard abandons draft changes.\"\n"},{at=193858,current="L[\"Via Script/Macro\"] = true\nL[\"Use a unique Via Script/Macro identifier.\"] = true\n",previous=""},{at=194073,current="",previous="L[\"Use a unique Via Macro identifier.\"] = true\n"},{at=194291,current="L[\"Help.Announces.type.macro\"] = \"Via Script/Macro is invoked by its saved Identifier rather than a cast event. It does not require a stored spell or item. Current conditions must match before any output. This call attempts output synchronously; it does not establish that a spell was cast or succeeded.\"\n",previous="L[\"Help.Announces.type.macro\"] = \"Via Macro is invoked by its saved Identifier rather than a cast event. It does not require a stored spell or item. Current conditions must match before any output. This call attempts output synchronously; it does not establish that a spell was cast or succeeded.\"\n"},{at=194959,current="L[\"Help.Announces.macro.example\"] = \"Use /run RM_Annouce('FOO','mouseover',nil). RM_Announce is the same function. The target unit and spell are optional: /run RM_Announce('FOO',nil,403) or /run RM_Announce('FOO','target','Lightning Bolt'). Spell names depend on client language. {{event}} becomes Via Script/Macro; {{target}} and {{spell}} use the supplied arguments. A required missing argument skips output. {{item}} is not supplied by this API. A resurrection message announces an attempt, not a completed resurrection. Examples are text only; RM does not create or execute macros.\"\n",previous="L[\"Help.Announces.macro.example\"] = \"Use /run RM_Annouce('FOO','mouseover',nil). RM_Announce is the same function. The target unit and spell are optional: /run RM_Announce('FOO',nil,403) or /run RM_Announce('FOO','target','Lightning Bolt'). Spell names depend on client language. {{event}} becomes Via Macro; {{target}} and {{spell}} use the supplied arguments. A required missing argument skips output. {{item}} is not supplied by this API. A resurrection message announces an attempt, not a completed resurrection. Examples are text only; RM does not create or execute macros.\"\n"},{at=196151,current="L[\"Help.Announces.channel.say\"] = \"Available only for Via Script/Macro. Attempt a Say message directly in the invoking call. Blizzard may reject macro-origin chat, including during instance encounters; RM does not attest hardware input, defer delivery, retry or guarantee visible output.\"\nL[\"Help.Announces.channel.yell\"] = \"Available only for Via Script/Macro. Attempt a Yell message directly in the invoking call. Native macro and encounter restrictions still apply; a completed API call is not confirmation of delivery.\"\nL[\"Help.Announces.channel.whisper\"] = \"Available only for Via Script/Macro. Whisper uses the exact supplied unit name and requires a readable player identity. No target means no Whisper. Native macro and encounter restrictions still apply; RM never substitutes another recipient or retries.\"\n",previous="L[\"Help.Announces.channel.say\"] = \"Available only for Via Macro. Attempt a Say message directly in the invoking call. Blizzard may reject macro-origin chat, including during instance encounters; RM does not attest hardware input, defer delivery, retry or guarantee visible output.\"\nL[\"Help.Announces.channel.yell\"] = \"Available only for Via Macro. Attempt a Yell message directly in the invoking call. Native macro and encounter restrictions still apply; a completed API call is not confirmation of delivery.\"\nL[\"Help.Announces.channel.whisper\"] = \"Available only for Via Macro. Whisper uses the exact supplied unit name and requires a readable player identity. No target means no Whisper. Native macro and encounter restrictions still apply; RM never substitutes another recipient or retries.\"\n"},{at=198270,current="L['Help.Announces.channel.channel']='Via Script/Macro outputs can send to a joined chat channel. Open Channel to refresh the joined names, then select the exact name. A saved name remains visible when unavailable; that output is skipped until the channel is joined under that name. Numeric channel IDs are not saved and channels are never joined automatically. Native delivery permissions still apply.'\n",previous="L['Help.Announces.channel.channel']='Via Macro outputs can send to a joined chat channel. Open Channel to refresh the joined names, then select the exact name. A saved name remains visible when unavailable; that output is skipped until the channel is joined under that name. Numeric channel IDs are not saved and channels are never joined automatically. Native delivery permissions still apply.'\n"},{at=198674,current="L['Choose an announcement trigger, then edit its always expanded output cards. Each card has a destination, conditions, enabled state and Help. Add, duplicate, delete, move or drag outputs within the announcement. Joined channel names are available for Via Script/Macro. New opens a draft; Apply saves it and Discard restores it. Imports are validated and never execute code.']='Choose an announcement trigger, then edit its always expanded output cards. Each card has a destination, conditions, enabled state and Help. Add, duplicate, delete, move or drag outputs within the announcement. Joined channel names are available for Via Script/Macro. New opens a draft; Apply saves it and Discard restores it. Imports are validated and never execute code.'\n",previous="L['Choose an announcement trigger, then edit its always expanded output cards. Each card has a destination, conditions, enabled state and Help. Add, duplicate, delete, move or drag outputs within the announcement. Joined channel names are available for Via Macro. New opens a draft; Apply saves it and Discard restores it. Imports are validated and never execute code.']='Choose an announcement trigger, then edit its always expanded output cards. Each card has a destination, conditions, enabled state and Help. Add, duplicate, delete, move or drag outputs within the announcement. Joined channel names are available for Via Macro. New opens a draft; Apply saves it and Discard restores it. Imports are validated and never execute code.'\n"}}}
