records["UI/settings_form.lua"]={bytes=38036,hash=1943047464,oldBytes=35570,oldHash=1062779351,changes={{at=492,current="    local p={frame=addon:TrackWorkbenchSize(CreateFrame('Frame',nil,parent)),pool={},counts={},fields={},edits={},cleanups={},active=false,generation=0,isSettingsForm=true}\n",previous="    local p={frame=CreateFrame('Frame',nil,parent),pool={},counts={},fields={},edits={},cleanups={},active=false,generation=0,isSettingsForm=true}\n"},{at=698,current="",previous="    addon:SetUIScript(p.frame,\"OnHide\",function()if p.stopStockObservation then p.stopStockObservation()end end)\n"},{at=2611,current="        return function(...) if self:Valid(token) then local result;if self.WithSettingsHistory then result=self:WithSettingsHistory(callback,...) else result=callback(...) end;if self.transactionKeys and self.fields.apply and not self.creationUsedForNew then if self:IsSettingsDraftDirty() then self.fields.apply:Enable() else self.fields.apply:Disable() end end;return result end end\n",previous="        return function(...) if self:Valid(token) then local result;if self.WithSettingsHistory then result=self:WithSettingsHistory(callback,...) else result=callback(...) end;if self.transactionKeys and self.fields.apply and not self.creationUsedForNew then if self:IsSettingsDraftDirty() then self.fields.apply:Enable() else self.fields.apply:Disable() end end;if self.updateStockObservationActions then self.updateStockObservationActions()end;return result end end\n"},{at=3157,current="        local c=self.pool[kind][i];if not c then c=build();addon:TrackWorkbenchRegion(c);self.pool[kind][i]=c end;if c.SetParent then c:SetParent(self.surface or self.child) end;c:Show();return c\n",previous="        local c=self.pool[kind][i];if not c then c=build();self.pool[kind][i]=c end;if c.SetParent then c:SetParent(self.surface or self.child) end;c:Show();return c\n"},{at=6480,current="            c.tooltip=entry.text;if icon then c.icon:SetTexture(addon:ControlTexture(icon));c:SetText('');c:SetWidth(20) else c:SetText(entry.text);c:SetWidth(math.min(110,self.width)) end\n            -- A row that no longer fits wraps instead of running past the pane.\n            if x>0 and x+c:GetWidth()>self.width then x=0;y=y+28;self.y=self.y+28 end\n            c:ClearAllPoints();c:SetPoint('TOPLEFT',x,-y);x=x+c:GetWidth()+4\n",previous="            c:ClearAllPoints();c:SetPoint('TOPLEFT',x,-y);c.tooltip=entry.text;if icon then c.icon:SetTexture(addon:ControlTexture(icon));c:SetText('');c:SetWidth(20) else c:SetText(entry.text);c:SetWidth(110) end;x=x+c:GetWidth()+4\n"},{at=27751,current="        local promptWidth=addon:FitWorkbenchPrompt(prompt.frame,self.frame,430);prompt.text:SetWidth(math.max(1,promptWidth-24))\n",previous=""},{at=29337,current="        -- The four channels share the row beside the swatch in two columns.\n        local channelWidth=math.max(40,(self.width-278-4)/2)\n",previous=""},{at=29529,current="            local c=self:Acquire('colorInputs',function() return addon:CreateWorkbenchEditBox(self.child) end);c:ClearAllPoints();c:SetPoint('TOPLEFT',278+((i-1)%2)*(channelWidth+4),-y-math.floor((i-1)/2)*26);c:SetSize(channelWidth,24);c:SetText(string.format('%.3f',values[channel]));c:SetTextColor(1,1,1);c:EnableMouse(true);c:ClearFocus();c:SetTextInsets(16,3,0,0)\n",previous="            local c=self:Acquire('colorInputs',function() return addon:CreateWorkbenchEditBox(self.child) end);c:ClearAllPoints();c:SetPoint('TOPLEFT',278+((i-1)%2)*84,-y-math.floor((i-1)/2)*26);c:SetSize(80,24);c:SetText(string.format('%.3f',values[channel]));c:SetTextColor(1,1,1);c:EnableMouse(true);c:ClearFocus();c:SetTextInsets(16,3,0,0)\n"},{at=32136,current="    -- Every cleanup runs even if one fails; a failure part-way used to leave\n    -- the old page's controls on screen and the page unusable.\n    function p:RunCleanups()\n        local cleanups=self.cleanups;self.cleanups={}\n        for _,cleanup in ipairs(cleanups) do\n            local ok,why=pcall(cleanup)\n            if not ok then local handler=geterrorhandler and geterrorhandler();if handler then pcall(handler,why) end end\n        end\n    end\n",previous=""},{at=32870,current="        self:RunCleanups()\n",previous="        for _,cleanup in ipairs(self.cleanups) do cleanup() end;self.cleanups={}\n"},{at=32995,current="        self.creationUsed=false;self.creationUsedForNew=false;self.counts={};self.fields={};self.edits={};if self.ResetLayout then self:ResetLayout() end;self.y=4;self.width=math.max(340,self.frame:GetWidth()-40);self.child:SetWidth(self.width)\n",previous="        self.creationUsed=false;self.creationUsedForNew=false;self.counts={};self.fields={};self.edits={};if self.ResetLayout then self:ResetLayout() end;self.y=4;self.width=math.max(340,math.min(760,self.frame:GetWidth()-40));self.child:SetWidth(self.width)\n"},{at=33533,current="",previous="        if self.checkStockObservationOwner then self.checkStockObservationOwner()end\n"},{at=34399,current="        addon:ReserveWorkbenchHelpCorner(self.frame,self.scroll,8)\n",previous=""},{at=34699,current="    -- Geometry alone changed: draw again at the new width, carrying every\n    -- pending input across as typed (invalid text included) without\n    -- committing it, so a resize never loses or silently applies an edit.\n    function p:Relayout()\n        if not self.active then return end\n        for _,record in ipairs(self.edits) do\n            if record.control.HasFocus and record.control:HasFocus() then\n                -- Typing keeps its control, text and caret; draw again once\n                -- the input lets go. A newer drawing supersedes this wait.\n                self.relayoutWaiter=self.relayoutWaiter or CreateFrame('Frame',nil,self.frame)\n                local token=self.generation\n                addon:SetUIScript(self.relayoutWaiter,'OnUpdate',function(waiter)\n                    if not self.active or self.generation~=token then addon:SetUIScript(waiter,'OnUpdate',nil);return end\n                    for _,current in ipairs(self.edits) do if current.control.HasFocus and current.control:HasFocus() then return end end\n                    addon:SetUIScript(waiter,'OnUpdate',nil);self:Relayout()\n                end)\n                return\n            end\n        end\n        local pending={}\n        for _,record in ipairs(self.edits) do if record.dirty then for key,control in pairs(self.fields) do if control==record.control then pending[key]=control:GetText() end end end end\n        self:Draw()\n        for key,text in pairs(pending) do\n            local control=self.fields[key]\n            for _,record in ipairs(self.edits) do if control and record.control==control then\n                control:SetText(text);record.dirty=true\n                local valid=record.parse(text)~=nil;control:SetTextColor(1,valid and 1 or .35,valid and 1 or .35)\n                if self.transactionKeys and self.fields.apply then self.fields.apply:Enable() end\n            end end\n        end\n    end\n    function p:SetWidth(n) local changed=n~=self.frame:GetWidth();self.frame:SetWidth(n);self:Layout();if changed then self:Relayout() end end\n",previous="    function p:SetWidth(n) local changed=n~=self.frame:GetWidth();self.frame:SetWidth(n);self:Layout();if changed and self.active and self:FlushEdits() then self:Draw() end end\n"},{at=36847,current="",previous="        if self.stopStockObservation then self.stopStockObservation()end\n"},{at=37208,current="        self:RunCleanups()\n",previous="        for _,cleanup in ipairs(self.cleanups) do cleanup() end;self.cleanups={}\n"}}}
